+
+function parseLimit(raw: unknown): number | null {
+  if (typeof raw !== 'number' || !Number.isInteger(raw)) return null;
+  return raw >= 0 ? raw : null;
+}
+
+function parseCursor(raw: unknown): SessionCursor | null {
+  if (typeof raw !== 'object' || raw === null) return null;
+  const cursor = raw as Record<string, unknown>;
+  if (!validSessionId(cursor.sessionId) || !validCursorTime(cursor.updatedAt)) return null;
+  return {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId};
+}
+
+function validSessionId(value: unknown): value is string {
+  if (typeof value !== 'string') return false;
+  return value.length >= 1 && value.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function validCursorTime(value: unknown): value is string | number {
+  if (typeof value === 'number') return Number.isFinite(value);
+  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
+  return false;
+}
